let inflight: Promise<Tokens> | null = null;
export function refreshOnce() {
  if (!inflight) inflight = refreshToken()
    .then(async t => { await saveTokensAtomically(t); return t; })
    .finally(() => { inflight = null; });
  return inflight;
}
api.interceptors.response.use(null, async (err) => {
  if (err.response?.status !== 401 || err.config._retry) throw err;
  err.config._retry = true;
  const t = await refreshOnce();
  err.config.headers.Authorization = `Bearer ${t.access}`;
  return api(err.config);
});
